def bq_row_count_validation(**context):
    """
    Queries the BigQuery audit table and displays the row count for the current load.
    The query fetches the count of records inserted today, matching the Teradata logic.
    """
    from google.cloud import bigquery
    from airflow.exceptions import AirflowFailException
    from datetime import datetime
    import logging

    logging.basicConfig(level=logging.INFO)
    ti = context['ti']
    
    # Get the execution date (date used in the Teradata query)
    dict_obs = ti.xcom_pull(task_ids='startTask', key='dict_obs')
    if not dict_obs:
        logging.error("Could not retrieve XCom 'dict_obs' from startTask.")
        raise AirflowFailException("Missing start task metadata.")

    # Get the required metadata for the target BigQuery table
    target_metadata = context['dag'].get_task('load_audit_to_bq').metadataParams
    dataset_id = target_metadata['hook']['datasetId']
    table_id = target_metadata['hook']['tableId']
    project_id = target_metadata['hook']['projectId']
    
    # The final table name, dynamically formatted
    target_table = f"{project_id}.{dataset_id}.{table_id}"
    
    # The Teradata query uses CURRENT_DATE(), so we check the BQ table 
    # for the corresponding insertion date to validate only the latest load.
    # We use the process_date calculated in startTask as the validation date.
    validation_date = dict_obs.get('process_date') 
    
    if not validation_date:
        # Fallback to current date in case process_date is missing
        validation_date = datetime.now().strftime("%Y-%m-%d")

    # The column names in the BQ table schema (validation_date, databasename, tablename, count, environmentname)
    # The Teradata query result (c1, c2, c3, c4, c5) maps to these columns, where 
    # c1 is CURRENT_DATE(), which populates the validation_date column.
    bq_sql = f"""
        SELECT 
            tablename, 
            sum(count) as row_count_from_td 
        FROM 
            `{target_table}`
        WHERE 
            DATE(validation_date) = DATE('{validation_date}')
        GROUP BY 
            tablename
        ORDER BY
            tablename
    """
    
    logging.info(f"Executing BigQuery Row Count Validation for load date: {validation_date}")
    logging.info(f"SQL:\n{bq_sql}")

    # Initialize BigQuery client and execute query
    try:
        client = bigquery.Client()
        query_job = client.query(bq_sql)
        results = query_job.result()
        
        # Display results in a clear table format
        header = f"\n{'-'*50}\n| {'Table Name':<30} | {'Row Count':<15} |\n{'-'*50}"
        logging.info(header)
        
        total_count = 0
        detail_results = []
        for row in results:
            table_name = row['tablename']
            row_count = row['row_count_from_td']
            total_count += row_count
            detail_results.append(f"| {table_name:<30} | {row_count:<15} |")

        for line in detail_results:
            logging.info(line)
        
        footer = f"{'-'*50}\n| {'TOTAL ROWS VALIDATED':<30} | {total_count:<15} |\n{'-'*50}"
        logging.info(footer)

    except Exception as e:
        logging.error(f"Failed to query BigQuery table {target_table}: {e}")
        # Fail the DAG if the critical validation query itself fails
        raise AirflowFailException(f"BigQuery validation failed: {e}")

